using api::v2::Types::Search_t = struct Search_t
   {

       std::string keyword;  


       std::string filter;  


       std::string order_by;  


       std::string direction;  


       size_t      limit;  


       size_t      offset;  


       Search_t(const jsoncons::json& search_j, bool& success)  
       {





           try
           {
               const jsoncons::json &kw = search_j.at("keyword"), &fl = search_j.at("filter"), &ob = search_j.at("order_by"), &dr = search_j.at("direction"),
                                    &lm = search_j.at("limit"), &of = search_j.at("offset");  





               if (!kw.is_string() || !fl.is_string() || !ob.is_string() || !dr.is_int64() || !lm.is_int64() || !of.is_int64())  
               {
                   success = false;  
                   return;           
               }
               keyword   = kw.as<std::string>();             
               filter    = fl.as<std::string>();             
               order_by  = ob.as<std::string>();             
               direction = dr.as<short>() == 0 ? "ASC" : "DESC";  
               limit     = lm.as<size_t>();                  
               offset    = of.as<size_t>();                  
               success   = validate(search_j);               
           }
           catch (const std::exception&)  
           {
               success = false;  
           }
       }



       static bool isPlainIdentifier(const std::string& name)  
       {
           constexpr size_t MAX_IDENTIFIER_LENGTH = 63;  
           if (name.empty() || name.size() > MAX_IDENTIFIER_LENGTH || std::isdigit(static_cast<unsigned char>(name.front())) != 0)  
           {
               return false;  
           }
           return std::ranges::all_of(name, [](char c) { return std::isalnum(static_cast<unsigned char>(c)) != 0 || c == '_'; });  
       }


       bool validate(const jsoncons::json& search_j)  
       {
           static const std::unordered_set<std::string> keys = {"keyword", "filter", "order_by", "direction", "limit", "offset"};  
           return search_j.size() == keys.size() && std::ranges::all_of(keys, [&search_j](const std::string& key) { return search_j.find(key).has_value(); }) && isPlainIdentifier(filter) &&
                  isPlainIdentifier(order_by);  
       }
   }

using api::v2::Types::ClientLoginData = struct ClientLoginData
