       std::optional<std::string>          lastLogoutTime;   
       std::optional<std::string>          nowLoginTime;     
       bool                                is_active;        
       bool                                passwordMatch;    
       std::optional<std::string>          passwordHash;     
       std::chrono::system_clock::duration expireTime;       
       std::optional<std::string>          ip_address;       
   }

